dir:

































  &DefaultButton;




function dir$dmttxnk(p){
  this.constructor(p);
}
dir$dmttxnk.prototype = new DirEvent();
dir$dmttxnk.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmttxnk.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmttxnkDisabledMasterField(p, g);

}

function dir$dmttxnkDisabledMasterField(p, g){

  if(p.valForm('ma_tt').trim() != '')
  {
    p.setDisabled('ma_tt', true);
  }
  else
  {
    p.setDisabled('ma_tt', false);
  }
}









declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã trạng thái đã tồn tại' else N'Status code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã trạng thái đã tồn tại' else N'Status code already exists' end
